<template>
 <div class="mobile-page" v-loading="loading">
  <header><div class="brand">现场设备核验</div><el-tag :type="task.status==='COMPLETED'?'success':task.status==='FAILED'?'danger':'warning'">{{statusLabel}}</el-tag></header>
  <el-result v-if="error" icon="error" title="链接无效" :sub-title="error" />
  <template v-else-if="task.taskNo">
   <section class="summary"><b>{{task.workflowNo}}</b><div>{{task.merchantCode}} · {{task.merchantName}}</div><div>铺位：{{task.stallCode}} {{task.stallName}}</div><div>待核验设备：{{task.devices?.length||0}} 台</div></section>
   <el-button v-if="['PENDING','OPENED'].includes(task.status)" class="primary-action" type="primary" size="large" @click="start">开始现场核验</el-button>
   <div v-for="(device,index) in task.devices||[]" :key="device.id" class="device-card">
    <div class="device-title"><span>{{index+1}}. {{device.deviceNameSnapshot||device.platformDeviceId}}</span><el-tag>{{device.energyType==='WATER'?'水表':'电表'}}</el-tag></div>
    <div class="source-data">
     <div class="source-heading"><span>系统原始数据</span><el-tag size="small" type="info">仅供现场核对，不可修改</el-tag></div>
     <template v-if="device.energyType==='WATER'">
      <div class="source-item"><small>水表序列号</small><strong>{{device.expectedSerialNumber||'系统暂无数据'}}</strong></div>
      <div v-if="device.expectedCommAddress" class="source-item"><small>通讯地址</small><strong>{{device.expectedCommAddress}}</strong></div>
     </template>
     <template v-else>
      <div class="source-item"><small>电表号/通讯地址</small><strong>{{device.expectedCommAddress||'系统暂无数据'}}</strong></div>
      <div class="source-item"><small>电表序列号</small><strong>{{device.expectedSerialNumber||'系统暂无数据'}}</strong></div>
     </template>
     <div v-if="device.productNameSnapshot" class="source-item"><small>产品名称</small><strong>{{device.productNameSnapshot}}</strong></div>
    </div>
    <div class="photo-guide"><b>{{photoTitle(device)}}</b><span>{{photoGuide(device)}}</span></div>
    <el-form label-position="top" :disabled="task.status!=='IN_PROGRESS'">
     <el-form-item :label="`当前累计读数（${device.readingUnit}）`"><el-input-number v-model="device.onsiteReading" :min="0" :precision="3" size="large" style="width:100%" /></el-form-item>
     <el-form-item v-if="device.meterPhase==='THREE_PHASE'" label="电表倍率"><el-input-number v-model="device.onsiteMultiplier" :min="0.0001" :precision="4" :step="1" size="large" style="width:100%" placeholder="请输入现场倍率" /></el-form-item>
     <div class="photos"><PhotoUpload :label="faceLabel(device)" type="METER_FACE" :device="device" :token="token" @done="loadPhotos(device)"/><PhotoUpload v-if="needsSerialPhoto(device)" label="电表号照片 *" type="SERIAL_NUMBER" :device="device" :token="token" @done="loadPhotos(device)"/></div>
     <div class="photo-count">已上传：表盘 {{countPhoto(device,'METER_FACE')}} 张<span v-if="needsSerialPhoto(device)">，电表号 {{countPhoto(device,'SERIAL_NUMBER')}} 张</span></div>
    </el-form>
   </div>
   <el-input v-if="task.status==='IN_PROGRESS'" v-model="remark" type="textarea" :rows="3" placeholder="本次核验总体备注（可选）" />
   <el-button v-if="task.status==='IN_PROGRESS'" class="primary-action" type="success" size="large" @click="complete">完成全部核验</el-button>
   <el-result v-if="['COMPLETED','FAILED'].includes(task.status)" :icon="task.status==='COMPLETED'?'success':'warning'" :title="task.status==='COMPLETED'?'核验已完成':'核验发现不一致'" sub-title="结果已经记录，请关闭此页面。" />
  </template>
 </div>
</template>
<script setup lang="ts">
import { computed,defineComponent,h,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { ElButton,ElMessage,ElMessageBox,ElProgress,ElUpload } from 'element-plus';import { verificationApi } from '@/api/verification'
const route=useRoute(),token=String(route.params.token),task=ref<any>({}),loading=ref(false),error=ref(''),remark=ref('');const statusLabel=computed(()=>({PENDING:'待打开',OPENED:'已打开',IN_PROGRESS:'核验中',COMPLETED:'已完成',FAILED:'核验异常'} as any)[task.value.status]||task.value.status)
const PhotoUpload=defineComponent({props:{label:String,type:String,device:Object,token:String},emits:['done'],setup(p,{emit}){const state=ref<'idle'|'uploading'|'success'|'error'>('idle'),progress=ref(0),message=ref('');return()=>h('div',{class:['photo-upload',`is-${state.value}`]},[h(ElUpload,{showFileList:false,accept:'image/jpeg,image/png',disabled:task.value.status!=='IN_PROGRESS'||state.value==='uploading',httpRequest:async(o:any)=>{state.value='uploading';progress.value=1;message.value='照片正在上传，请不要关闭页面或进行其他操作';try{await verificationApi.upload(p.token!,Number((p.device as any).id),p.type!,o.file,(v:number)=>progress.value=v);progress.value=100;state.value='success';message.value='照片上传成功，系统已保存';emit('done');ElMessage.success(`${p.label}上传成功`)}catch(e){state.value='error';message.value='上传失败，请检查网络后重新上传';ElMessage.error(`${p.label}上传失败，请重试`);throw e}}},{trigger:()=>h(ElButton,{size:'large',plain:true,loading:state.value==='uploading',disabled:task.value.status!=='IN_PROGRESS'||state.value==='uploading'},()=>state.value==='uploading'?`正在上传 ${progress.value}%`:`拍摄/上传${p.label}`)}),state.value==='uploading'?h(ElProgress,{percentage:progress.value,strokeWidth:10,status:undefined}):null,state.value!=='idle'?h('div',{class:'upload-feedback'},[h('span',{class:'feedback-icon'},state.value==='success'?'✓':state.value==='error'?'!':'↥'),h('span',message.value)]):null])}})
async function load(){loading.value=true;try{task.value=await verificationApi.open(token);for(const d of task.value.devices||[])await loadPhotos(d)}catch(e:any){error.value=e?.message||'无法访问核验任务'}finally{loading.value=false}}async function start(){task.value=await verificationApi.start(token);for(const d of task.value.devices||[])await loadPhotos(d)}
async function loadPhotos(d:any){d.attachments=await verificationApi.attachments(token,d.id)}function countPhoto(d:any,t:string){return(d.attachments||[]).filter((a:any)=>a.photoType===t).length}
function needsSerialPhoto(d:any){return d.energyType==='ELECTRIC'&&d.meterPhase!=='THREE_PHASE'}
function photoTitle(d:any){return d.energyType==='WATER'?'水表拍照要求':d.meterPhase==='THREE_PHASE'?'三相电表拍照要求':'单相电表拍照要求'}
function photoGuide(d:any){return d.energyType==='WATER'?'拍摄一张照片，必须同时清晰显示水表表号和当前读数。':d.meterPhase==='THREE_PHASE'?'拍摄一张表盘照片，必须同时清晰显示印刷电表号和当前读数。':'需要两张照片：一张清晰显示当前读数，一张清晰显示电表号/序列号。'}
function faceLabel(d:any){return d.energyType==='WATER'?'水表表盘照片（含表号和读数）*':d.meterPhase==='THREE_PHASE'?'电表表盘照片（含表号和读数）*':'电表读数照片 *'}
async function complete(){for(const d of task.value.devices||[]){if(d.onsiteReading===null||d.onsiteReading===undefined){ElMessage.warning(`请填写“${d.deviceNameSnapshot||d.platformDeviceId}”的当前读数`);return}if(d.meterPhase==='THREE_PHASE'&&(d.onsiteMultiplier===null||d.onsiteMultiplier===undefined||Number(d.onsiteMultiplier)<=0)){ElMessage.warning(`请填写“${d.deviceNameSnapshot||d.platformDeviceId}”的电表倍率`);return}if(countPhoto(d,'METER_FACE')<1){ElMessage.warning(`请上传“${d.deviceNameSnapshot||d.platformDeviceId}”的表盘照片`);return}if(needsSerialPhoto(d)&&countPhoto(d,'SERIAL_NUMBER')<1){ElMessage.warning(`请上传“${d.deviceNameSnapshot||d.platformDeviceId}”的电表号照片`);return}}await ElMessageBox.confirm('确认所有设备读数、倍率和照片清晰完整并提交？','提交现场核验');loading.value=true;try{for(const d of task.value.devices||[])await verificationApi.saveDevice(token,d.id,{onsiteReading:d.onsiteReading,onsiteMultiplier:d.meterPhase==='THREE_PHASE'?d.onsiteMultiplier:null});task.value=await verificationApi.complete(token,remark.value);ElMessage.success('现场核验已提交')}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>.mobile-page{max-width:680px;margin:auto;min-height:100vh;background:#f5f7fa;padding:14px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.brand{font-size:20px;font-weight:700}.summary,.device-card{background:#fff;border-radius:14px;padding:16px;margin-bottom:14px;box-shadow:0 4px 18px #1f29370f}.summary div{margin-top:8px;color:#606266}.device-title{display:flex;justify-content:space-between;font-size:17px;font-weight:600;margin-bottom:12px}.source-data{display:grid;grid-template-columns:1fr 1fr;gap:10px;background:#f7f8fa;border:1px solid #e4e7ed;padding:12px;border-radius:10px;margin-bottom:12px}.source-heading{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center;font-weight:600}.source-item{min-width:0;background:#fff;border-radius:8px;padding:10px}.source-item small,.source-item strong{display:block}.source-item small{color:#909399;margin-bottom:5px}.source-item strong{color:#303133;word-break:break-all;font-size:15px}.photo-guide{display:flex;flex-direction:column;gap:6px;background:#ecf5ff;color:#337ecc;padding:12px;border-radius:10px;margin-bottom:16px;line-height:1.55}.photo-guide span{color:#52606d}.photos{display:grid;gap:10px;margin-top:12px}.photos :deep(.el-button){width:100%;min-height:48px;white-space:normal;height:auto;padding:12px}.photo-upload{padding:10px;border:1px solid #dcdfe6;border-radius:10px;background:#fafafa}.photo-upload :deep(.el-upload){width:100%}.photo-upload :deep(.el-progress){margin-top:10px}.upload-feedback{display:flex;align-items:center;gap:8px;margin-top:9px;padding:8px 10px;border-radius:7px;font-size:14px}.is-uploading .upload-feedback{color:#337ecc;background:#ecf5ff}.is-success{border-color:#95d475;background:#f0f9eb}.is-success .upload-feedback{color:#529b2e;background:#e1f3d8;font-weight:600}.is-error{border-color:#f89898;background:#fef0f0}.is-error .upload-feedback{color:#c45656;background:#fde2e2}.feedback-icon{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;font-weight:700}.photo-count{font-size:13px;color:#73767a;margin:10px 0}.primary-action{width:100%;min-height:50px;margin:12px 0;font-size:16px}@media(max-width:480px){.mobile-page{padding:10px}.device-card{padding:14px}.device-title{align-items:flex-start;gap:8px}.source-data{grid-template-columns:1fr}.source-heading{grid-column:1}.source-heading{align-items:flex-start;gap:8px}}</style>

